CREATE POLICY category_images_owner_insert ON storage.objects AS RESTRICTIVE FOR INSERT TO authenticated WITH CHECK (NOT (bucket_id='product-images' AND name LIKE 'platform/categories/%') OR public.has_role(auth.uid(),'super_admin'));
CREATE POLICY category_images_owner_update ON storage.objects AS RESTRICTIVE FOR UPDATE TO authenticated USING (NOT (bucket_id='product-images' AND name LIKE 'platform/categories/%') OR public.has_role(auth.uid(),'super_admin')) WITH CHECK (NOT (bucket_id='product-images' AND name LIKE 'platform/categories/%') OR public.has_role(auth.uid(),'super_admin'));
CREATE POLICY category_images_owner_delete ON storage.objects AS RESTRICTIVE FOR DELETE TO authenticated USING (NOT (bucket_id='product-images' AND name LIKE 'platform/categories/%') OR public.has_role(auth.uid(),'super_admin'));